<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda Harian BPSDM · {{$day->translatedFormat('d F Y')}}</title><link rel="icon" href="{{asset('assets/img/favicon/inte.png')}}"><link rel="stylesheet" href="{{asset('assets/vendor/fonts/boxicons.css')}}"><link rel="stylesheet" href="{{asset('assets/vendor/css/core.css')}}"><link rel="stylesheet" href="{{asset('assets/vendor/css/theme-default.css')}}">
<style>
