ckground:#fff}.summary i{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#edf0ff;color:var(--primary);font-size:22px}.summary small,.summary strong{display:block}.summary small{color:var(--muted);font-size:10px}.summary strong{font-size:20px}.group{margin-bottom:22px}.group-title{display:flex;align-items:center;gap:11px;margin-bottom:10px}.group-title h2{margin:0;font-size:15px;font-weight:800;letter-spacing:.025em}.group-title span{padding:4px 8px;border-radius:20px;background:#e9edff;color:var(--primary);font-size:9px;font-weight:700}.group-title:after{height:1px;flex:1;background:var(--line);content:""}.agenda-list{display:grid;gap:9px}.agenda-item{display:grid;grid-template-columns:120px minmax(0,1fr) auto;align-items:center;gap:18px;padding:17px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 3px 12px rgba(34,48,74,.04);transition:.2s}.agenda-item:hover{transform:translateY(-2px);box-shadow:0 10px 25px rgba(34,48,74,.09)}.agenda-item.is-ongoing{border-color:#71dd37;background:linear-gradient(90deg,#f3ffed,#fff);box-shadow:0 7px 22px rgba(113,221,55,.14)}.agenda-item.is-finished{opacity:.62}.agenda-time strong,.agenda-time small{display:block}.agenda-time strong{font-size:16px}.agenda-time small{color:var(--muted);font-size:10px}.agenda-content{min-width:0}.agenda-content h3{margin:0 0 5px;font-size:14px;line-height:1.4}.parent{display:block;margin-bottom:8px;color:var(--primary);font-size:10px;font-weight:600}.meta{display:flex;flex-wrap:wrap;gap:7px 16px;color:var(--muted);font-size:10px}.meta span,.meta a{display:flex;align-items:flex-start;gap:5px}.meta a{color:var(--primary);overflow-wrap:anywhere}.status{display:inline-flex;align-items:center;gap:5px;padding:6px 9px;border-radius:30px;font-size:9px;font-weight:700;white-space:nowrap}.status.upcoming{background:#e8f8fc;color:#03a4c8}.status.ongoing{background:#eafbdd;color:#4caa1b}.status.finished{background:#eff0f2;color:#8592a3}.dot{width:7px;height:7px;border-radius:50%;background:currentColor}.empty{padding:70px 20px;border:1px dashed #ccd2df;border-radius:20px;background:#fff;text-align:center}.empty i{font-size:55px;color:#a8b1c2}.empty p{color:var(--muted)}.toast-copy{position:fixed;right:22px;bottom:22px;z-index:50;padding:12px 16px;border-radius:12px;background:#22304a;color:#fff;box-shadow:0 12px 30px rgba(0,0,0,.18);opacity:0;transform:translateY(12px);transition:.2s;pointer-events:none}.toast-copy.show{opacity:1;transform:none}.scroll-state{position:fixed;left:18px;bottom:18px;z-index:15;padding:7px 10px;border-radius:30px;background:rgba(34,48,74,.86);color:#fff;font-size:9px}.scroll-state.paused{background:#ffab00}
