<script>(()=>{const today=@json($isToday),pastDate=@json($isPastDate),items=[...document.querySelectorAll('.agenda-item')],clock=document.getElementById('liveClock'),counter=document.getElementById('ongoingCount'),toast=document.getElementById('copyToast'),toggle=document.getElementById('toggleScroll'),state=document.getElementById('scrollState');let scrolling=true,lastAction=Date.now();function update(){const current=today?new Date():new Date('{{$date}}T'+(pastDate?'23:59:59':'00:00:00'));let ongoing=0;items.forEach(item=>{const start=new Date(item.dataset.start),end=new Date(item.dataset.end),badge=item.querySelector('.status'),label=item.querySelector('.status-label');let key,text;if(current<start){key='upcoming';text='Akan Datang'}else if(current>end){key='finished';text='Selesai'}else{key='ongoing';text='Sedang Berlangsung';ongoing++}item.classList.toggle('is-ongoing',key==='ongoing');item.classList.toggle('is-finished',key==='finished');badge.className='status '+key;label.textContent=text});counter.textContent=today?ongoing:'–';if(today)clock.textContent=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})+' WIB'}function notify(text){toast.querySelector('span').textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}async function copy(text,message){try{await navigator.clipboard.writeText(text);notify(message)}catch(e){window.prompt('Salin teks berikut:',text)}}document.getElementById('copyAgenda').onclick=()=>copy(document.getElementById('shareText').value,'Agenda siap ditempel ke WhatsApp');document.getElementById('copyLink').onclick=()=>copy(@json($shareUrl),'Link publik berhasil disalin');document.getElementById('agendaDate').onchange=e=>location.href=@json($shareUrl)+'?date='+e.target.value;document.getElementById('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();toggle.onclick=()=>{scrolling=!scrolling;toggle.innerHTML=scrolling?'<i class="bx bx-pause me-1"></i>Jeda':'<i class="bx bx-play me-1"></i>Mulai';state.classList.toggle('paused',!scrolling);state.innerHTML=scrolling?'<i class="bx bx-down-arrow-alt"></i> Auto-scroll aktif':'<i class="bx bx-pause"></i> Auto-scroll dijeda'};['wheel','pointerdown','touchstart'].forEach(name=>addEventListener(name,()=>lastAction=Date.now(),{passive:true}));setInterval(()=>{if(!scrolling||Date.now()-lastAction<7000||document.hidden)return;if(innerHeight+scrollY>=document.documentElement.scrollHeight-8)scrollTo({top:0,behavior:'smooth'});else scrollBy(0,1)},45);setInterval(update,30000);setInterval(()=>{if(Date.now()-lastAction>120000)location.reload()},300000);update()})();</script></body></html>
